const root = ReactDOM.createRoot(document.querySelector('#root'));

const Course = ({ title, hours }) => {
  const total = hours + 4;

  return (
    <article className="course">
      <h3 className="course__title">{title}</h3>
      <p className="course__meta">{hours}시간</p>
      <p className="course__total">보충 4시간 포함 {total}시간</p>
    </article>
  );
};

root.render(<Course title="자바스크립트 입문" hours={12} />);

const root = ReactDOM.createRoot(document.querySelector('#root'));

const Course = ({ title, hours, sale }) => (
  <article className="course">
    <h3 className="course__title">{title}</h3>
    <p className="course__meta">{hours}시간</p>
    <p className="course__total">보충 4시간 포함 {hours + 4}시간</p>
    <p className="course__sale">{sale ? '할인 중' : '정가'}</p>
  </article>
);

root.render(
  <>
    <Course title="자바스크립트 입문" hours={12} sale />
    <Course title="리액트 시작하기" hours={20} />
  </>
);
